import { BrowserRouter, Routes, Route, Link, Outlet } from "react-router";

function Layout() {
  return (
    <>
      <header><nav aria-label="Main"><Link to="/">Home</Link> <Link to="/courses">Courses</Link></nav></header>
      <main><Outlet /></main>          {/* the matched child route renders here. */}
    </>
  );
}

export function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route element={<Layout />}>
          <Route index element={<Home />} />
          <Route path="courses" element={<CourseList />} />
          <Route path="courses/:courseId" element={<Course />} />
          <Route path="*" element={<NotFound />} />
        </Route>
      </Routes>
    </BrowserRouter>
  );
}
```

| Navigation | Works if |
|---|---|
| clicking a Link. | the route is declared. |
| Back / Forward. | links used real paths. |
| refresh or shared link. | the host serves index.html for app paths. |
| unknown path. | a `*` route shows NotFound. |

